dripstone_caves_boulder.script:
num randPrecision = 100;
num radius = 1+randomInt(randPrecision)/randPrecision*2;
num warp = 2;
num warpFreq = 2.5;
num squish = 1+randomInt(randPrecision)/randPrecision/2;
num radiusSquared = pow(radius,2);
num yTranslate = -1;
num boulderType = randomInt(randPrecision)/randPrecision;

if (check(radius, -radius/squish, 0) != "LAND" ||
    check(-radius, -radius/squish, 0) != "LAND" ||
    check(0, -radius/squish, radius) != "LAND" ||
    check(0, -radius/squish, -radius) != "LAND"
    ) fail;

for (num x = -radius-warp; x < radius+warp; x = x + 1) {
    for (num y = (-radius-warp)/squish; y < (radius+warp)/squish; y = y + 1) {
        for (num z = -radius-warp; z < radius+warp; z = z + 1) {
            num warpX = warp * sampler("simplex3",
                                warpFreq*(x+originX()),
                                warpFreq*(y+originY()+1000),
                                warpFreq*(z+originZ()));
            num warpY = warp * sampler("simplex3",
                                warpFreq*(x+originX()),
                                warpFreq*(y+originY()+2000),
                                warpFreq*(z+originZ()));
            num warpZ = warp * sampler("simplex3",
                                warpFreq*(x+originX()),
                                warpFreq*(y+originY()+3000),
                                warpFreq*(z+originZ()));
			num distanceSquared = pow(x+warpX,2)+pow((y+warpY)*squish,2)+pow(z+warpZ,2);
            if (distanceSquared < radiusSquared / 2) {
				if (boulderType <= 0.65) {
                    structure(x, y+yTranslate, z, "granite_boulder_ores", "NONE");
                } else {
                    structure(x, y+yTranslate, z, "tuff_boulder_ores", "NONE");
                }
            }
			else if (distanceSquared < radiusSquared) {
				if (boulderType <= 0.65) {
                    block(x, y+yTranslate, z, "minecraft:granite");
                } else {
                    block(x, y+yTranslate, z, "minecraft:tuff");
                }
			}
        }
    }
}

dripstone_column.script:
num randPrecision = 100;
num maxRadius = 5 + 5*randomInt(randPrecision)/randPrecision;
num minRadius = -1 + maxRadius*0.5*randomInt(randPrecision)/randPrecision;
num maxDepth = 10;
num maxHeight = 100;
num warpFrequency = 15;
num warpAmplitude = 3;
str columnBlock = "minecraft:dripstone_block";
str replaceableMask = "is_dripstone_column_replaceable";

// Search downwards for a valid area to start from
num maxRadiusSquared = pow2(maxRadius);
num depth = maxDepth;
bool foundFloor = false;
bool hitFloor = false; // Used to prevent column piercing through terrain
for (num y = 0; y <= maxDepth; y = y + 1) {
    if (!structure(0, -y, 0, replaceableMask, "NONE")) {
        hitFloor = true;
        bool solidArea = true;
        for (num x = -maxRadius; x <= maxRadius; x = x + 1) {
            for (num z = -maxRadius; z <= maxRadius; z = z + 1) {
                if (pow2(x)+pow2(z) < maxRadiusSquared) {
                    if (structure(x, -y, z, replaceableMask, "NONE")) {
                        solidArea = false;
                        break;
                    }
                    if (!solidArea) break;
                }
            }
            if (!solidArea) break;
        }
        if (solidArea) {
            foundFloor = true;
            depth = y;
            break;
        }
    } else if (hitFloor) break;
}
if (!foundFloor) fail;

// Search upwards for a valid area to end at
num height = maxHeight;
bool foundCeiling = false;
bool hitCeiling = false; // Used to prevent column piercing through terrain
for (num y = 0; y <= maxHeight; y = y + 1) {
    if (!structure(0, y, 0, replaceableMask, "NONE")) {
        hitCeiling = true;
        bool solidArea = true;
        for (num x = -maxRadius; x <= maxRadius; x = x + 1) {
            for (num z = -maxRadius; z <= maxRadius; z = z + 1) {
                if (pow2(x)+pow2(z) < maxRadiusSquared) {
                    if (structure(x, y, z, replaceableMask, "NONE")) {
                        solidArea = false;
                        break;
                    }
                    if (!solidArea) break;
                }
            }
            if (!solidArea) break;
        }
        if (solidArea) {
            foundCeiling = true;
            height = y;
            break;
        }
    } else if (hitCeiling) break;
}
if (!foundCeiling) fail;

// Generate column
for (num y = -depth; y <= height; y = y + 1) {

    num t = (y+depth)/(height+depth);
    num diskRadius = minRadius + (maxRadius-minRadius)*pow2(2)*pow2(t-0.5);
    num diskRadiusCeil = ceil(diskRadius);
    num diskRadiusSquared = pow2(diskRadius);

    for (num x = -diskRadiusCeil; x <= diskRadiusCeil; x = x + 1) {
        for (num z = -diskRadiusCeil; z <= diskRadiusCeil; z = z + 1) {
            num distanceOffset = abs(sampler("simplex3",
                                         (originX()+x)*warpFrequency,
                                         (originY()+y)*warpFrequency,
                                         (originZ()+z)*warpFrequency)) * warpAmplitude;

            num distanceSquared = pow2(x)+pow2(z)+pow2(distanceOffset);
            if (distanceSquared < diskRadiusSquared) {
                if (structure(x, y, z, replaceableMask, "NONE")) block(x, y, z, columnBlock);
            }
        }
    }
}

eucalyptus_tree_procedural.script:
num randPrecision = 100;
num goldenAngle = 2.39996;
num pi = 3.14159;

num trunkHeight = 10+randomInt(8);
str trunkBlock = "minecraft:acacia_log";
str rootBlock = "minecraft:acacia_wood";

num sideBranchInterval = 0;
num sideBranchMinHeight = 3+randomInt(3);
num sideBranchLengthMin = 4+randomInt(2);
num sideBranchLengthVariation = 2;
num sideBranchVerticalVariation = 0;
num sideBranchVerticalDirection = 0.5+randomInt(randPrecision)/randPrecision/2;
num sideBranchLeafRadiusMin = 4;
num sideBranchLeafTranslate = 0;
num sideBranchLeafTopFlatness = 0.5;
num sideBranchLeafBottomFlatness = 2;
num sideBranchLeafDensity = 0.7;
str sideBranchLeafStructure = "acacia_leaves";
str sideBranchBlockX = "minecraft:acacia_log[axis=x]";
str sideBranchBlockY = "minecraft:acacia_log[axis=y]";
str sideBranchBlockZ = "minecraft:acacia_log[axis=z]";

num topBranches = 1;
num topBranchLengthUpwardsMin = 7+randomInt(3);
num topBranchLengthOutwardsMin = 0;
num topBranchVerticalDirection = 1;
num topBranchLeafRadiusMin = 4;
num topBranchLeafTranslate = 0;
num topBranchLeafTopFlatness = 0.7;
num topBranchLeafBottomFlatness = 1.5;
num topBranchLeafDensity = 0.7;
str topBranchLeafStructure = "acacia_leaves";
str topBranchBlockX = "minecraft:acacia_log[axis=x]";
str topBranchBlockY = "minecraft:acacia_log[axis=y]";
str topBranchBlockZ = "minecraft:acacia_log[axis=z]";

// Generate roots at base of trunk
num roots = 0;
num rootMaxDepth = 3;
num rootHeight = 5;
num rootLength = 2;
num rootAngle = randomInt(randPrecision)/randPrecision*2*pi;
for (num r = 0; r < roots; r = r + 1) {
    num dx = sin(rootAngle);
    num dz = cos(rootAngle);
    for (num l = 0; l <= rootLength; l = l + 1) {
        num height = rootHeight * (1-(l/rootLength));
        bool bottomedOut = false;
        for (num h = height; h >= -rootMaxDepth; h = h - 1) {
            if (check(round(l*dx),round(h),round(l*dz)) != "AIR") {
                bottomedOut = true;
                break;
            }
            block(l*dx, h, l*dz, rootBlock);
        }
        if (!bottomedOut) break;
    }
    rootAngle = rootAngle + goldenAngle;
}

num branchAngle = randomInt(randPrecision)/randPrecision*2*pi;
for (num i = 0; i < trunkHeight; i = i + 1) {
    if (i > sideBranchMinHeight) {
        if (i % sideBranchInterval == 0) {
            // Branch direction vector
            num dx = sin(branchAngle);
            num dy = sideBranchVerticalDirection + randomInt(randPrecision)/randPrecision*sideBranchVerticalVariation;
            num dz = cos(branchAngle);
            // Normalize vector
            num mag = sqrt(pow(dx,2)+pow(dy,2)+pow(dz,2));
            dx = dx/mag;
            dy = dy/mag;
            dz = dz/mag;
            // Branch origin
            num ox = 0;
            num oy = i;
            num oz = 0;
            // Set branch block based on largest unsigned vector component
            str branchBlock = sideBranchBlockY;
            if (abs(dx) > max(abs(dy),abs(dz))) branchBlock = sideBranchBlockX;
            else if (abs(dz) > max(abs(dy),abs(dx))) branchBlock = sideBranchBlockZ;
            num branchLength = sideBranchLengthMin + randomInt(randPrecision)/randPrecision*sideBranchLengthVariation;
            // Generate branch
            for (num l = 0; l <= branchLength; l = l + 1) {
                block(l*dx+ox, l*dy+oy, l*dz+oz, branchBlock);
            }
            // Rotate angle of next branch
            branchAngle = branchAngle + goldenAngle;
            // Generate leaf cluster at the end of the branch
            num radius = sideBranchLeafRadiusMin;
            num radiusSquared = pow(radius, 2);
            // Leaf cluster origin (end of branch)
            num lox = ox+branchLength*dx;
            num loy = oy+branchLength*dy + sideBranchLeafTranslate;
            num loz = oz+branchLength*dz;
            for (num cx = ceil(-radius); cx <= ceil(radius); cx = cx + 1) {
                for (num cy = ceil(-radius/sideBranchLeafBottomFlatness); cy <= ceil(radius/sideBranchLeafTopFlatness); cy = cy + 1) {
                    for (num cz = ceil(-radius); cz <= ceil(radius); cz = cz + 1) {
                        num squashFactor = sideBranchLeafBottomFlatness;
                        if (cy > 0) squashFactor = sideBranchLeafTopFlatness;
                        num distanceSquared = pow(cx,2)+pow(cy*squashFactor,2)+pow(cz,2);
                        if (distanceSquared < radiusSquared && randomInt(randPrecision)/randPrecision < sideBranchLeafDensity) {
                            structure(lox+cx, loy+cy, loz+cz, sideBranchLeafStructure, "NONE", "CW_90", "CCW_90", "CW_180");
                        }
                    }
                }
            }
        }
    }
    block(0, i, 0, trunkBlock);
}

for (num b = 1; b <= topBranches; b = b + 1) {
    num t = b/topBranches;
    num ti = 1-t;
    // Branch direction vector
    num dx = sin(branchAngle) * t;
    num dy = topBranchVerticalDirection;
    num dz = cos(branchAngle) * t;
    // Normalize vector
    num mag = sqrt(pow(dx,2)+pow(dy,2)+pow(dz,2));
    dx = dx/mag;
    dy = dy/mag;
    dz = dz/mag;
    // Branch origin
    num ox = 0;
    num oy = trunkHeight;
    num oz = 0;
    // Set branch block based on largest unsigned vector component
    str branchBlock = topBranchBlockY;
    if (abs(dx) > max(abs(dy),abs(dz))) branchBlock = topBranchBlockX;
    else if (abs(dz) > max(abs(dy),abs(dx))) branchBlock = topBranchBlockZ;
    num branchLength = topBranchLengthUpwardsMin*ti + topBranchLengthOutwardsMin*t;
    // Generate branch
    for (num l = 0; l <= branchLength; l = l + 1) {
        block(l*dx+ox, l*dy+oy, l*dz+oz, branchBlock);
    }
    // Rotate angle of next branch
    branchAngle = branchAngle + goldenAngle;
    // Generate leaf cluster at the end of the branch
    num radius = topBranchLeafRadiusMin;
    num radiusSquared = pow(radius, 2);
    // Leaf cluster origin (end of branch)
    num lox = ox+branchLength*dx;
    num loy = oy+branchLength*dy + topBranchLeafTranslate;
    num loz = oz+branchLength*dz;
    for (num cx = ceil(-radius); cx <= ceil(radius); cx = cx + 1) {
        for (num cy = ceil(-radius/topBranchLeafBottomFlatness); cy <= ceil(radius/topBranchLeafTopFlatness); cy = cy + 1) {
            for (num cz = ceil(-radius); cz <= ceil(radius); cz = cz + 1) {
                num squashFactor = topBranchLeafBottomFlatness;
                if (cy > 0) squashFactor = topBranchLeafTopFlatness;
                num distanceSquared = pow(cx,2)+pow(cy*squashFactor,2)+pow(cz,2);
                if (distanceSquared < radiusSquared && randomInt(randPrecision)/randPrecision < topBranchLeafDensity) {
                    structure(lox+cx, loy+cy, loz+cz, topBranchLeafStructure, "NONE", "CW_90", "CCW_90", "CW_180");
                }
            }
        }
    }
}

