red_mushroom_disk.script:
num randPrecision = 100;
num radius = 2+randomInt(4);
num innerRadius = radius-4;
num midRadius = radius-2;
num warpTop = 0.5;
num warpTopFrequency = 2;
num squish = 1.5+randomInt(randPrecision)/randPrecision;
num radiusHorizontal = round(radius + radius*warpTop);

str outerBlock = "minecraft:red_mushroom_block";
str innerBlock = "minecraft:red_mushroom_block[up=false,down=false,north=false,east=false,south=false,west=false]";
str spotBlock = "minecraft:mushroom_stem";

num radiusSquared = pow2(radius);
num innerRadiusSquared = pow2(innerRadius);
num midRadiusSquared = pow2(midRadius);
num distanceSquared = 0;

num ox = (randomInt(randPrecision)/randPrecision-0.5)*radius;
num oy = -radius/squish+2;
num oz = (randomInt(randPrecision)/randPrecision-0.5)*radius;

for (num x = -radiusHorizontal; x < radiusHorizontal; x = x + 1) {
    for (num y = 0; y < radius / squish; y = y + 1) {
        for (num z = -radiusHorizontal; z < radiusHorizontal; z = z + 1) {
            num warpX = sampler("simplex", warpTopFrequency*(originX()+x), warpTopFrequency*(originZ()+z)) * abs(y-midRadius) * warpTop;
            num warpZ = sampler("simplex", warpTopFrequency*(originZ()+x+1000), warpTopFrequency*(originZ()+z)) * abs(y-midRadius) * warpTop;
            distanceSquared = pow2(x+warpX)+pow2(y*squish)+pow2(z+warpZ);
            if (distanceSquared < radiusSquared && distanceSquared > innerRadiusSquared && y+1 >= abs(warpX+warpZ)) {
                if (distanceSquared > midRadiusSquared) {
                    if (randomInt(40) == 0) {
                        block(ox+x, oy+y, oz+z, spotBlock);
                    } else {
                        block(ox+x, oy+y, oz+z, outerBlock);
                    }
                } else {
                    block(ox+x, oy+y, oz+z, innerBlock);
                }
            }
        }
    }
}

red_rock.script:
num randPrecision = 100;
num radius = 2+randomInt(randPrecision)/randPrecision*4;
num warp = 5;
num warpFreq = 8;
// Randomize iceberg x,y,z 
num xRand = 1+randomInt(5);
num yRand = 1+randomInt(3);
num zRand = 1+randomInt(5);
num radiusSquared = pow(radius,2);
num yTranslate = 1;

for (num x = -radius-warp-xRand; x < radius+warp+xRand; x = x + 1) {
    for (num y = (-radius-(warp*yRand)); y < (radius+(warp*yRand)); y = y + 1) {
        for (num z = -radius-warp-zRand; z < radius+warp+zRand; z = z + 1) {
            num warpX = warp * sampler("simplex3",
                                warpFreq*(x+originX()),
                                warpFreq*(y+originY()+1000),
                                warpFreq*(z+originZ()));
            num warpY = warp * sampler("simplex3",
                                warpFreq*(x+originX()),
                                warpFreq*(y+originY()+2000),
                                warpFreq*(z+originZ()));
            num warpZ = warp * sampler("simplex3",
                                warpFreq*(x+originX()),
                                warpFreq*(y+originY()+3000),
                                warpFreq*(z+originZ()));

            // Iceberg equation
            num size = (pow(x+warpX,2)/xRand)+(pow((y+warpY),2)/yRand)+(pow(z+warpZ,2)/zRand);

            // Places iceberg blocks if within range
            if ( size < radiusSquared ) {
                block(x, y+yTranslate, z,"minecraft:stone");

                // Places snow aroundish top
                if ( (size) >= (radiusSquared-size) && (y > (6+randomInt(3))) ) {
                    block(x, y+yTranslate, z,"minecraft:terracotta");
                // Places blue ice aroundish bottom
                } else if ( (size) >= (radiusSquared-size) && (y < -(3+randomInt(3))) ) {
                    block(x, y+yTranslate, z,"minecraft:red_sand");
                } 
            } 
        }
    }
}

