num height = 1+randomInt(4);
for (num i = 0; i < height; i = i + 1) {
    block(0, i, 0, "minecraft:sugar_cane", false);
}

sweet_berry_bush_patch.script:
num count = 6 + randomInt(10); // 4-12

for (num p = 0; p < count; p = p + 1) {

  num theta = randomInt(360) * 3.14159/180; // Pick random angle
  num r = 5 - randomInt(randomInt(6) + 1);  // Pick random distance
                                            // Accounts for radial distribution favoring the center
  num x = cos(theta) * r;
  num z = sin(theta) * r;

  // Check from top downwards for valid spawn
  num y = 4;
  while (!structure(x, y, z, "plantable", "NONE")) {
    y = y - 1;
    if (y < -4) fail;
  }
  block(x, y, z, "minecraft:sweet_berry_bush[age=3]");
}

tree_trunk_mushroom_disk.script:
block(0, 0, 0, "minecraft:brown_mushroom_block[down=false]", false);
block(1, 0, 0, "minecraft:brown_mushroom_block[down=false]", false);
block(0, 0, 1, "minecraft:brown_mushroom_block[down=false]", false);
block(1, 0, 1, "minecraft:brown_mushroom_block[down=false]", false);

tree_vines.script:
// Generate a column of leaves down from ceiling block
num leafDepth = 2 + randomInt(2); // Length of center column of leaves
for (num i = 0; i < leafDepth; i = i + 1) block(0, -i, 0, "minecraft:oak_leaves[persistent=true]", false);

// Add shorter columns of leaves directly adjacent if adjacent ceiling blocks are present
if (check(0, 0, -1) == "LAND") {
    num leafDepthNorth = randomInt(floor(leafDepth));
    for (num i = 0; i < leafDepthNorth; i = i + 1) block(0, -i, -1, "minecraft:oak_leaves[persistent=true]", false);
}
if (check(0, 0, 1) == "LAND") {
    num leafDepthSouth = randomInt(floor(leafDepth));
    for (num i = 0; i < leafDepthSouth; i = i + 1) block(0, -i, 1, "minecraft:oak_leaves[persistent=true]", false);
}
if (check(1, 0, 0) == "LAND") {
    num leafDepthEast = randomInt(floor(leafDepth));
    for (num i = 0; i < leafDepthEast; i = i + 1) block(1, -i, 0, "minecraft:oak_leaves[persistent=true]", false);
}
if (check(-1, 0, 0) == "LAND") {
    num leafDepthWest = randomInt(floor(leafDepth));
    for (num i = 0; i < leafDepthWest; i = i + 1) block(-1, -i, 0, "minecraft:oak_leaves[persistent=true]", false);
}

// Finally add vines of random lengths coming from center column
num vineDepthNorth = randomInt(10);
for (num i = leafDepth; i < leafDepth + vineDepthNorth; i = i + 1) block(0, -i, -1, "minecraft:vine[south=true]", false);
num vineDepthSouth = randomInt(10);
for (num i = leafDepth; i < leafDepth + vineDepthSouth; i = i + 1) block(0, -i, 1, "minecraft:vine[north=true]", false);
num vineDepthEast = randomInt(10);
for (num i = leafDepth; i < leafDepth + vineDepthEast; i = i + 1) block(1, -i, 0, "minecraft:vine[west=true]", false);
num vineDepthWest = randomInt(10);
for (num i = leafDepth; i < leafDepth + vineDepthWest; i = i + 1) block(-1, -i, 0, "minecraft:vine[east=true]", false);

tuff_boulder_ores.script:
num blockSelection = randomInt(34);
if(blockSelection <= 27) block(0, 0, 0, "minecraft:tuff");
else if(blockSelection <= 33) block(0, 0, 0, "minecraft:raw_iron_block");

waterfall.script:
str topBlock = "minecraft:tuff";
str wallBlock = "minecraft:mossy_cobblestone";
str waterBlock = "minecraft:water";
str flowingWaterBlock = "minecraft:water[level=8]";
str airBlock = "minecraft:air";
num width = 1;
num length = 4;
num inwardLength = -3;
num downwardsMaxSearch = 50;

num dirX = 0;
num dirZ = 0;

if (getBlock(1, 0, 0) == "minecraft:stone") {
    dirX = -1;
    if (getBlock(0, 0, -1) == "minecraft:stone" || getBlock(0, 0, 1) == "minecraft:stone") {
        fail;
    }
} else if (getBlock(-1, 0, 0) == "minecraft:stone") {
    if (getBlock(0, 0, -1) == "minecraft:stone" || getBlock(0, 0, 1) == "minecraft:stone") {
        fail;
    }
    dirX = 1;
} else if (getBlock(0, 0, 1) == "minecraft:stone") {
    if (getBlock(1, 0, 0) == "minecraft:stone" || getBlock(-1, 0, 0) == "minecraft:stone") {
        fail;
    }
    dirZ = -1;
} else if (getBlock(0, 0, -1) == "minecraft:stone") {
    if (getBlock(1, 0, 0) == "minecraft:stone" || getBlock(-1, 0, 0) == "minecraft:stone") {
        fail;
    }
    dirZ = 1;
}

// floor
for (num j = -width; j <= width; j = j + 1) {
    for (num i = inwardLength; i <= length; i = i + 1) {

        str usedBlock = topBlock;
        if (randomInt(5) > 3) {
            usedBlock = wallBlock;
        }

        block(dirX * i + dirZ * j, 0, dirZ * i + dirX * j, usedBlock);
        block(dirX * i + dirZ * j, 1, dirZ * i + dirX * j, waterBlock);
        block(dirX * i + dirZ * j, 2, dirZ * i + dirX * j, airBlock);
            for (num k = 1; k <= (length - i) / 2; k = k + 1) {

                if (randomInt(5) > 3) {
                    usedBlock = wallBlock;
                }
                block(dirX * i + dirZ * j, -k, dirZ * i + dirX * j, usedBlock);
            }
    }
}

// wall
for (num j = -width - 1; j <= width + 1; j = j + 1) {
    if ((j == -width - 1) || (j == width + 1)) {
        for (num i = inwardLength; i <= length; i = i + 1) {

            str usedBlock = topBlock;
            if (randomInt(5) > 3) {
                usedBlock = wallBlock;
            }

            block(dirX * i + dirZ * j, 1, dirZ * i + dirX * j, usedBlock);
        }
    }
}

// waterfall itself
num fails = 0;

for (num j = -1; j <= downwardsMaxSearch; j = j + 1) {

    num offset = length + 1;

    if (getBlock(dirX * offset, -j, dirZ *  offset) != "minecraft:air") {
        fails = fails + 1;
        if (fails > 3) {
            break;
        }
    }

    for (num i = -width; i <= width; i = i + 1) {
        block(dirX * offset + dirZ * i, -j, dirZ * offset + dirX * i, flowingWaterBlock, true);
    }
}

